import{_ as r,o,c as n,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Tentacle - Dashboard","description":"","frontmatter":{"title":"CDS Tentacle - Dashboard","date":"2024-08-22T00:00:00.000Z","updated":"2024-08-23T00:00:00.000Z","tags":["Ceph","Dashboard","Development","Storage","Multi","Cluster"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/CDS_Tentacle_-_Dashboard.md","filePath":"posts/2024/CDS_Tentacle_-_Dashboard.md","lastUpdated":1780459816000}'),l={name:"posts/2024/CDS_Tentacle_-_Dashboard.md"};function a(e,t,i,g,p,_){return o(),n("div",null,[...t[0]||(t[0]=[s("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年X月X日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： 全体开发者</p><p><strong>会议主题</strong>： Dashboard 开发者峰会</p><p><strong>会议内容</strong>：</p><p><strong>一、Scripx 和 Squid 改进</strong></p><ul><li>Scripx：改进了导航布局，增加了 SFS 相关功能，包括快照和克隆管理、快照调度、文件系统管理助手等，修复了一些 bug。</li><li>Squid：增加了 RGW 存储桶策略管理，支持添加和删除存储桶标签，改进了 UI/UX，实现了 RGW 分析功能，可视化存储桶和用户分析数据。</li></ul><p><strong>二、Tentacle 计划</strong></p><ul><li><strong>多集群功能</strong>： Tentacle 将是第一个支持多集群功能的版本。可以将多个集群连接到一个中心集群，实现单集群管理。已完成大部分实现，包括安全性和 UX 改进。需要进行性能测试，目标是支持 50 到 100 个集群。</li><li><strong>SE 管理网关</strong>： 为 SE 集群上的所有监控堆栈提供单一入口点，提高安全性。即使节点故障，也能保证仪表板和 RESTful API 的正常运行。大部分功能已经实现，将继续迭代和改进。</li><li><strong>NVMe 改进</strong>： 将 NVMe 管理功能从 UI 中提供，计划引入网关组和相关功能，支持 MTL。</li><li><strong>工作流程</strong>： 讨论了多个工作流程，包括多站点自动化、NVMe 部署、FS 工作流程和 RBD 镜像。将根据用户反馈和设计进行优先级排序。</li><li><strong>Carbon 迁移</strong>： 计划将所有页面迁移到 Carbon，提高性能和可维护性。将进行性能测试，确保不损失性能。</li><li><strong>依赖项升级</strong>： 升级 Angular 到最新版本，以提高安全性和可维护性。将升级其他依赖项。</li><li><strong>监控</strong>： 计划添加多集群视图、改进 RGW 分析仪表板、支持集群 ID 过滤和改进警报。将升级 Grafana 到最新版本。</li><li><strong>RGW</strong>： 实现了细粒度的存储桶复制策略管理。计划在 UI 中实现 S3 管理。</li><li><strong>测试覆盖率</strong>： 提高 API 测试覆盖率。改进测试覆盖率和测试自动化。</li></ul><p><strong>三、后续行动计划</strong></p><ul><li>继续开发 Tentacle 功能。</li><li>完成多集群测试。</li><li>发布博客文章。</li><li>召开 UX 设计会议。</li><li>升级 Grafana。</li><li>与其他开发者合作，改进测试和监控。</li></ul><p><strong>四、其他事项</strong></p><ul><li>讨论了 RBD 镜像工作流程和测试覆盖率的改进。</li><li>讨论了 Landing 页面改进和 Carbon 迁移。</li></ul><p><strong>五、会议总结</strong></p><p>本次会议讨论了 Dashboard 的多个改进和计划，包括 Tentacle 功能、多集群、SE 管理网关、NVMe、工作流程、Carbon 迁移、依赖项升级、监控、RGW 和测试覆盖率。会议明确了后续行动计划，并鼓励开发者积极参与。</p>",16)])])}const S=r(l,[["render",a]]);export{c as __pageData,S as default};
